head.script:
// 같은 데이터(CANDLESTICK.json: OHLC + trdvolume)로 두 차트를 상하 렌더
scwin.URL ="/ui/sample/SBChart/CANDLESTICK/data/CANDLESTICK.json";
scwin.DATES = [];   // 인덱스→날짜 매핑용 (x축은 인덱스를 주므로 사전 조회한 날짜로 변환)

// ---- 차트 공통 상수 (SPCHART.md 회신 §1 반영) ----
scwin.CHART_UP_COLOR   = "#E52528";   // 상승 : 빨강
scwin.CHART_DOWN_COLOR = "#1B64DA";   // 하락 : 파랑

/**
 * 차트 컨테이너를 정리한다. 재조회 렌더 전 호출 — 이전 차트 잔존 방지 (SPCHART.md §1-5)
 */
scwin.clearChart = function (comp) {
    const el = document.getElementById(comp.getID());
    if (el) { el.innerHTML = ""; }
};

// 날짜 MM-DD 로 변환 (인덱스 v → scwin.DATES[v]); 과밀 방지로 3개당 1개만
scwin.xdate = function (v) {
    const d = scwin.DATES[v];
    if (!d) { return ""; }
    return (v % 3 === 0) ? d.slice(5) : "";
};

// 화면에서 1회 조회(await) → 날짜 매핑 + 같은 데이터로 두 차트 렌더 (공통함수는 변환+렌더만)
scwin.onpageload = async function () {
    const res = await $c.sbm.executeDynamic({ id: "sbm_sbchart", action: scwin.URL, method: "get", mediatype: "application/json", mode: "asynchronous", isProcessMsg: false });
    const data = res.responseJSON;
    const rows = (data && data.json) ? data.json : [];
    scwin.DATES = rows.map(function (r) { return r.date; });
    scwin.render(data);
};

scwin.render = function (data) {
    scwin.clearChart(chartTop);   // 재조회 대비 이전 차트 정리 — SPCHART.md §1-5
    scwin.clearChart(chartVol);

    // ── 상단: 캔들스틱 (x축 날짜 MM-DD) ──
    $c.ext.drawChartData("candlestick", data, chartTop, {
        legend: { show: false },                                  // 캔들 범례 숨김
        tooltip: {
            width: "200px",
            format: {   // 마우스오버 표시값 — OHLC 한글 라벨 + 천단위 콤마 — SPCHART.md §1-7
                title: function (idx) { return scwin.DATES[idx] || ""; },
                // values 순서 = keys.value[0] 선언 순서 — [0]시가 [1]종가 [2]저가 [3]고가
                value: function (values, ratio, id, index) {
                    const fmt = function (v) { return $c.num.formatNumber(v) + " 원"; };
                    return {
                        open:  { key: "시가", value: fmt(values[0]) },
                        close: { key: "종가", value: fmt(values[1]) },
                        low:   { key: "저가", value: fmt(values[2]) },
                        high:  { key: "고가", value: fmt(values[3]) }
                    };
                }
            }
        },
        axis: {
            y: { min: 78000 },
            x: { tick: { format: scwin.xdate } }               // 인덱스 → 날짜(MM-DD)
        },
        extend: {
            candlestick: {
                auto: true,                                       // 상승/하락 자동 색
                inColor: scwin.CHART_UP_COLOR,                    // 상승 색 명시 — SPCHART.md §1-3
                deColor: scwin.CHART_DOWN_COLOR,                  // 하락 색 명시
                marker: { show: true, color: "#c0392b" }          // 고점/저점 값 마커
            }
        },
        dataOpts: {
            keys: { x: "date", value: [ { open: "openprc", close: "closeprc", low: "lowprc", high: "highprc" } ] }
        }
    });

    // ── 하단: 거래량 막대 (라벨 숨김, 날짜는 캔들 쪽에 표시) ──
    $c.ext.drawChartData("bar", data, chartVol, {
        legend: { show: false },
        tooltip: {
            format: {   // 마우스오버 표시값 — 천단위 콤마 — SPCHART.md §1-7
                title: function (idx) { return scwin.DATES[idx] || ""; },
                value: function (v, ratio, id, index) { return $c.num.formatNumber(v) + " 주"; }
            }
        },
        axis: {
            y: { tick: { format: function (v) { return Math.round(v / 10000) + "만"; } } },  // 거래량 만 단위
            x: { tick: { format: function () { return ""; } } }   // 하단 라벨 숨김
        },
        extend: { bar: { width: { ratio: 0.5 } } },
        dataOpts: { keys: { x: "date", value: [ "trdvolume" ] } }
    });
};
